# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">COĞRAFİ SAHA ÇALIŞMASI BASAMAKLARI (COĞ.10.3.4)</text>\n  <rect x="20" y="45" width="205" height="165" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="122" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. SAHA ÖNCESİ HAZIRLIK</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• Amaç ve araştırma sorusu belirleme</text>\n  <text x="32" y="108" font-size="10.8" fill="#1e3a8a">• Literatür ve önceki çalışmaları tarama</text>\n  <text x="32" y="128" font-size="10.8" fill="#1e3a8a">• Topoğrafya ve jeoloji haritası temini</text>\n  <text x="32" y="148" font-size="10.8" fill="#1e3a8a">• Güzergâh ve istasyon planlaması</text>\n  <text x="32" y="168" font-size="10.8" fill="#1e3a8a">• Araç-gereç (GPS, pusula, altimetre)</text>\n  <text x="32" y="188" font-size="10.8" fill="#1e3a8a">• İzinler ve güvenlik tedbirleri</text>\n  <rect x="247" y="45" width="205" height="165" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. SAHADA UYGULAMA VE VERİ</text>\n  <text x="260" y="88" font-size="10.8" fill="#14532d">• Doğrudan arazi gözlemi yapma</text>\n  <text x="260" y="108" font-size="10.8" fill="#14532d">• Kayaç, toprak ve tortul numunesi</text>\n  <text x="260" y="128" font-size="10.8" fill="#14532d">• GPS ile konum ve yükselti ölçümü</text>\n  <text x="260" y="148" font-size="10.8" fill="#14532d">• Eğim, bakı ve doğrultu ölçümü</text>\n  <text x="260" y="168" font-size="10.8" fill="#14532d">• Fotoğraflama ve arazi kesiti çizimi</text>\n  <text x="260" y="188" font-size="10.8" fill="#14532d">• Gözlem formuna verileri kaydetme</text>\n  <rect x="475" y="45" width="205" height="165" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="577" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. ÇÖZÜMLEME VE RAPORLAMA</text>\n  <text x="488" y="88" font-size="10.8" fill="#581c87">• Toplanan verileri sınıflandırma</text>\n  <text x="488" y="108" font-size="10.8" fill="#581c87">• CBS ve sanal küre ile haritalama</text>\n  <text x="488" y="128" font-size="10.8" fill="#581c87">• Doğal süreç-şekil ilişkisini kurma</text>\n  <text x="488" y="148" font-size="10.8" fill="#581c87">• Gelecekteki değişimi tahmin etme</text>\n  <text x="488" y="168" font-size="10.8" fill="#581c87">• Görsel, profil ve tablo oluşturma</text>\n  <text x="488" y="188" font-size="10.8" fill="#581c87">• Saha araştırma raporunu sunma</text>\n  <rect x="20" y="222" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Arazide gidilemeyen durumlarda CBS, uydu görüntüleri ve sayısal yükselti modelleriyle Sanal Saha Çalışması yapılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN BEŞERÎ FAALİYETLERE ETKİSİ (COĞ.10.3.5)</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">DAĞLIK VE ENGEBELİ ALANLAR</text>\n  <text x="34" y="88" font-size="10.8" fill="#78350f">• Nüfus seyrek, yerleşme dağınıktır</text>\n  <text x="34" y="110" font-size="10.8" fill="#78350f">• Tarım alanları dar ve parçalıdır</text>\n  <text x="34" y="132" font-size="10.8" fill="#78350f">• Yol yapım maliyeti çok yüksektir</text>\n  <text x="34" y="154" font-size="10.8" fill="#78350f">• Yaylacılık, mera hayvancılığı gelişir</text>\n  <text x="34" y="176" font-size="10.8" fill="#78350f">• Hidroelektrik potansiyel ve kış turizmi</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">OVALAR VE ALÜVYAL TABANLAR</text>\n  <text x="257" y="88" font-size="10.8" fill="#064e3b">• Nüfus yoğun, yerleşme topludur</text>\n  <text x="257" y="110" font-size="10.8" fill="#064e3b">• Tarımsal üretim ve makineli tarım</text>\n  <text x="257" y="132" font-size="10.8" fill="#064e3b">• Ulaşım ağları sık ve maliyeti düşüktür</text>\n  <text x="257" y="154" font-size="10.8" fill="#064e3b">• Tarıma dayalı sanayi ve ticaret</text>\n  <text x="257" y="176" font-size="10.8" fill="#064e3b">• Örnek: Çukurova, Gediz, Bafra ovaları</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PLATOLAR VE KIYI KUŞAĞI</text>\n  <text x="480" y="88" font-size="10.8" fill="#1e3a8a">• Platolarda tahıl tarımı ve küçükbaş</text>\n  <text x="480" y="110" font-size="10.8" fill="#1e3a8a">• Yüksek platolarda büyükbaş mera</text>\n  <text x="480" y="132" font-size="10.8" fill="#1e3a8a">• Çatalca-Kocaeli: Sanayi ve ulaşım</text>\n  <text x="480" y="154" font-size="10.8" fill="#1e3a8a">• Koy, körfez ve kıyılarda liman-turizm</text>\n  <text x="480" y="176" font-size="10.8" fill="#1e3a8a">• Karstik ve volkanik şekiller: Jeoturizm</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Yükselti, eğim, bakı ve dağların uzanışı; yerleşme, ulaşım, tarım ve turizm faaliyetlerini doğrudan yönlendirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BEŞERÎ FAALİYETLERİN YERYÜZÜ ŞEKİLLERİNE ETKİSİ VE SÜRDÜRÜLEBİLİRLİK</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">ANTROPOJENİK (İNSAN KAYNAKLI) MÜDAHALELER</text>\n  <text x="35" y="88" font-size="11" fill="#7f1d1d">• Tünel, viyadük, köprü ve geçit inşası (ulaşım)</text>\n  <text x="35" y="110" font-size="11" fill="#7f1d1d">• Kıyı dolgusu ile havalimanı, liman ve yol yapımı</text>\n  <text x="35" y="132" font-size="11" fill="#7f1d1d">• Açık işletme maden ocakları ve taş ocakları</text>\n  <text x="35" y="154" font-size="11" fill="#7f1d1d">• Baraj gölleriyle akarsu vadilerinin su altında kalması</text>\n  <text x="35" y="176" font-size="11" fill="#7f1d1d">• Eğimli yamaçların taraçalandırılması (sekileme)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">YANLIŞ ARAZİ KULLANIMI VE DOĞAL RİSKLER</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• Verimli alüvyal ovaların sanayi ve konuta açılması</text>\n  <text x="370" y="110" font-size="11" fill="#14532d">• Dere yataklarının doldurulması → Sel ve taşkın</text>\n  <text x="370" y="132" font-size="11" fill="#14532d">• Yamaç dengesinin bozulması → Heyelan ve kaya düşmesi</text>\n  <text x="370" y="154" font-size="11" fill="#14532d">• Bitki örtüsü tahribi → Hızlandırılmış toprak erozyonu</text>\n  <text x="370" y="176" font-size="11" fill="#14532d">• Çözüm: Arazi yetenek sınıflamasına uygun planlama</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">İnsan doğanın şekillendirici bir paydaşı (antropojenik etken) haline gelmiştir; sürdürülebilir planlama şarttır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
